import org.w3c.dom.Node;

import java.io.File;
import java.util.*;

public class DuplicateResourceDetector extends Detector implements XmlScanner, ResourceFolderScanner {

    public static final Issue DUPLICATE_DEFINITION = Issue.create(
            "DuplicateDefinition",
            "Duplicate resource definition",
            "Defining the same resource more than once in the same resource folder is usually an error.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(DuplicateResourceDetector.class, Scope.ALL_RESOURCES_SCOPE)
    );

    // Map from folder path to set of names already reported, to avoid duplicate reports.
    // Also map from folder to resource type+name -> list of locations? Need track for cross-file duplicates.
    private final Map<String, Set<String>> mReportedFileResources = new HashMap<>();
    private final Map<String, Map<String, List<Location.Handle>>> mValueResources = new HashMap<>();

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mReportedFileResources.clear();
        mValueResources.clear();
    }

    // ResourceFolderScanner
    @Override
    public void checkResourceFolder(@NonNull ResourceFolderContext context) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == null) {
            return;
        }
        File folder = context.getFolder();
        File[] files = folder.listFiles();
        if (files == null || files.length == 0) {
            return;
        }

        if (folderType == ResourceFolderType.VALUES) {
            // Values duplicates handled by XML scanning.
            return;
        }

        // Group by resource name (basename without extension)
        Map<String, List<File>> nameToFiles = new HashMap<>();
        for (File file : files) {
            if (file.isDirectory() || file.isHidden()) {
                continue;
            }
            String name = getResourceName(file);
            if (name == null) {
                continue;
            }
            nameToFiles.computeIfAbsent(name, k -> new ArrayList<>()).add(file);
        }

        String folderPath = folder.getAbsolutePath();
        Set<String> reported = mReportedFileResources.computeIfAbsent(folderPath, k -> new HashSet<>());
        for (Map.Entry<String, List<File>> entry : nameToFiles.entrySet()) {
            List<File> list = entry.getValue();
            if (list.size() <= 1) {
                continue;
            }
            String resName = entry.getKey();
            if (!reported.add(resName)) {
                continue;
            }
            // Report duplicate for each additional file referencing first
            Location firstLocation = Location.create(list.get(0));
            String message = String.format("Duplicate resource `%1$s` in %2$s folder", resName, folderType.getName());
            for (int i = 1; i < list.size(); i++) {
                Location location = Location.create(list.get(i));
                context.report(DUPLICATE_DEFINITION, location, message, firstLocation);
            }
        }
    }

    private static String getResourceName(File file) {
        String fileName = file.getName();
        int dot = fileName.indexOf('.');
        if (dot == -1) {
            return fileName;
        }
        return fileName.substring(0, dot);
    }

    // XmlScanner
    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL; // We inspect all elements to detect <string name=...> etc.
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType != ResourceFolderType.VALUES) {
            return;
        }
        if (element.getParentNode() == null || element.getParentNode().getNodeType() != Node.ELEMENT_NODE) {
            return;
        }
        Element parent = (Element) element.getParentNode();
        if (!"resources".equals(parent.getTagName())) {
            return;
        }
        String type = element.getTagName();
        String name = element.getAttributeNS(null, "name");
        if (name == null || name.isEmpty()) {
            if ("item".equals(type)) {
                type = element.getAttributeNS(null, "type");
                name = element.getAttributeNS(null, "name");
            }
            if (name == null || name.isEmpty() || type == null || type.isEmpty()) {
                return;
            }
        }
        String key = type + "/" + name;
        File folder = context.file.getParentFile();
        if (folder == null) return;
        String folderPath = folder.getAbsolutePath();
        Map<String, List<Location.Handle>> folderMap = mValueResources.computeIfAbsent(folderPath, k -> new HashMap<>());
        List<Location.Handle> locations = folderMap.computeIfAbsent(key, k -> new ArrayList<>());
        locations.add(context.getLocation(element));
        // If duplicate, report? We can report when list size == 2 (first duplicate) and also subsequent.
        // But need not report all at end? We can report as we encounter additional definitions.
        // However we need location of first too. Location handles can resolve to Location later.
    }

