public void checkFolder(ResourceContext context, String folderName) {
    ResourceFolderType folderType = ResourceFolderType.getFolderType(folderName);
    if (folderType == ResourceFolderType.VALUES) return;
    File folder = context.file;
    File[] files = folder.listFiles();
    if (files == null) return;
    Multimap<String, File> map = ArrayListMultimap.create();
    for (File file : files) {
        if (!file.isFile()) continue;
        String name = getResourceName(file.getName());
        if (name.isEmpty()) continue;
        map.put(name, file);
    }
    for (String name : map.keySet()) {
        Collection<File> filesForName = map.get(name);
        if (filesForName.size() < 2) continue;
        String message = String.format("Resource `%1$s` appears more than once in the `%2$s` folder", name, folderName);
        boolean first = true;
        Location firstLocation = null;
        for (File file : filesForName) {
            Location location = Location.create(file);
            if (first) {
                firstLocation = location;
                first = false;
            } else {
                context.report(DUPLICATE_DEFINITION, location, message);
            }
        }
    }
}
